riableNames: ''	classVariableNames: ''	poolDictionaries: ''	category: 'Mathematics-SymbolicManipulation'!Object subclass: #PointRotation	instanceVariableNames: 'a11 a12 a13 a21 a22 a23 a31 a32 a33 h i a b c d e f g '	classVariableNames: ''	poolDictionaries: ''	category: 'Mathematics-SymbolicManipulation'!!PointRotation commentStamp: 'jmi 5/16/2000 11:30' prior: 0!I am a PointRotation.  I know how to rotate points.  I was written with one thing in mind, speed.!!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 17:42'!* arg	"Answer the product expression of the receiver and arg"	^ self class newProduct firstTerm: self secondTerm: arg! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 17:43'!+ arg	"Answer the sum expression of the receiver and arg"	^ self class newSum firstTerm: self secondTerm: arg! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 17:43'!- arg	"Answer the difference expression of the receiver and arg"	^ self class newDifference firstTerm: self secondTerm: arg! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 17:43'!/ arg	"Answer the quotient expression of the receiver and arg"	^ self class newQuotient firstTerm: self secondTerm: arg! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:56'!abs	"Answer an expression equivalent to the absolute value of the receiver"	^ self squared sqrt! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:59'!negated	"Answer an expression equivalent to the negation of the receiver"	"alternate:		^ self * -1.	"	^ (self class newConstant: 0) - self! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 17:46'!raisedTo: arg	"Answer the exponential expression of the receiver and arg"	^ self class newExponential firstTerm: self secondTerm: arg! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:59'!reciprocal	"Answer an expression equivalent to the reciprocal of the receiver"	"alternate:		^ self raisedTo: -1.	"	^ (self class newConstant: 1) / self! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 4/23/2000 19:13'!sqrt	"Answer my square root"	^ self raisedTo: 0.5! !!Expression methodsFor: 'arithmetic' stamp: 'jmi 5/14/2000 21:58'!squared	"Answer myself squared"	"alternate:   	^ self * self "^ self raisedTo: 2.! !!Expression methodsFor: 'evaluation' stamp: 'jmi 5/14/2000 22:00'!evaluateAt: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	^ self subclassResponsibility! !!Expression methodsFor: 'evaluation' stamp: 'jmi 5/14/2000 22:04'!partialEvaluationAt: anAssociation	"Evaluate my expression using the value association.	It takes a little longer than evaluateAt:, but can be useful	when optimizing functions of multiple variables"	^ self subclassResponsibility! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:28'!cos	"Answer the cosine of the receiver"	^ self class newCos term: self! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:39'!cot	"Answer the cotangent of the receiver"	^ (self class newTan term: self) reciprocal! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:39'!csc	"Answer the cosecant of the receiver"	^ (self class newSin term: self) reciprocal! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 18:57'!ln	"Answer the natural logarithm of the receiver"	^ self class newNaturalLog term: self! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:39'!sec	"Answer the secant of the receiver"	^ (self class newCos term: self) reciprocal! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:28'!sin	"Answer the sine of the receiver"	^ self class newSin term: self! !!Expression methodsFor: 'mathematical functions' stamp: 'jmi 4/23/2000 20:35'!tan	"Answer the tangent of the receiver"	^ self class newTan term: self! !!Expression methodsFor: 'operation' stamp: 'jmi 5/15/2000 22:23'!operation	"Answer the symbol for the operation I represent"	^ self subclassResponsibility! !!Expression methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:16'!operationString	"Answer the string for the operation I represent	This only needs to be overidden by classes in which the commonly used symbol differs from the one Squeak uses.  for example, the carrat ^ is usually used for exponentialization, but in squeak it's used for returning values.  Therefore, operation needs to return #raisedTo: and operationString returns '^' "	^ self operation asString! !!Expression methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:35'!printSqueak	"Answer a string representation of my expression that can be evaluated by 'Compiler evaluate:' "	^ self subclassResponsibility! !!Expression methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:34'!printString	"Answer a string representation of my expression"	^ self subclassResponsibility! !!Expression methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 16:53'!reduceConstantSubexpressions	"Answer myself with any  with constant suxexpressions evaluated."		"Default action is to do nothing"	^ self! !!Expression methodsFor: 'private-initialization' stamp: 'jmi 5/16/2000 16:28'!simplify	"Answer a simplified expression"	^ self		reduceConstantSubexpressions		simplifyExpression! !!Expression methodsFor: 'private-initialization' stamp: 'jmi 4/23/2000 20:50'!simplifyExpression	"Allow my instances to attempt to reduce themselves on instance creation.	For example, the addition expression could override reduceExpression to ckeck for its identity	and return an equivalent, reduced equation.	1+0 would be reduced to 1"		"Default action is to do nothing"	^ self! !!Expression methodsFor: 'symbolic' stamp: 'jmi 5/15/2000 14:11'!derivative	"Answer my (partial) derivitive.  Can someone verify this is correct?"				"The variables typically come out backwards from the way I like them,				 so I reversed the array.  No real reason other than that."		^ self derivative: self variables asArray reversed.! !!Expression methodsFor: 'symbolic' stamp: 'jmi 5/15/2000 14:08'!derivative: array	"Answer my (partial) derivitive, with respect to the array of variables.  Can someone verify this is correct?"	| derivative |		"Initialize derivative to zero, since the derivative of a constant expression is always zero"	derivative _ self class newConstant: 0.		"Take the sum of the partial derivatives"	array do:	[:variable |		derivative _ derivative + (self derivativeWithRespectTo: variable).	].		"Answer the derivative"	^ derivative! !!Expression methodsFor: 'symbolic' stamp: 'jmi 5/14/2000 22:15'!derivativeWithRespectTo: aSymbolOrString	"Answer the my derivitive (partial or whatever) with respect to aSymbolOrString"	^ self privateDerivativeWithRespectTo: aSymbolOrString asSymbol! !!Expression methodsFor: 'symbolic-private' stamp: 'jmi 4/26/2000 11:20'!privateDerivativeWithRespectTo: aSymbolOrString	"Answer the my derivitive (partial or whatever) with respect to aSymbolOrString"	"This is what you add to a new operation,	 and this is the method you call to calculate derivatives	 of your subexpressions from WITHIN instance methods"	^ self subclassResponsibility! !!Expression methodsFor: 'testing' stamp: 'jmi 5/14/2000 22:18'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	"This should do a tree comparison rather than printString."	^ self printString = arg printString! !!Expression methodsFor: 'as yet unclassified' stamp: 'jmi 5/15/2000 17:45'!asExpression	"Answer myself, since I'm already an Expression"	^ self! !!Expression methodsFor: 'as yet unclassified' stamp: 'jmi 5/15/2000 14:05'!variables	"Answer a Set of all the variables I contain"	^ self addVariablesTo: Set new.! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/24/2000 17:46'!newConstant: aStringOrNumber	"Answer a new instance of the constant expression"	^ self constantClass new value: aStringOrNumber asNumber! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 20:36'!newCos	"Answer a new instance of the cosine expression"	^ self cosineClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:10'!newDifference	"Answer a new instance of the subtraction expression"	^ self differenceClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:45'!newExponential	"Answer a new instance of the exponential expression"	^ self exponentialClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 18:56'!newNaturalLog	"Answer a new instance of the natural logarithm expression"	^ self naturalLogarithmClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:11'!newProduct	"Answer a new instance of the multiplication expression"	^ self productClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:11'!newQuotient	"Answer a new instance of the division expression"	^ self quotientClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 20:36'!newSin	"Answer a new instance of the sine expression"	^ self sineClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 17:08'!newSum	"Answer a new instance of the addition expression"	^ self sumClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/23/2000 20:36'!newTan	"Answer a new instance of the cosine expression"	^ self tangentClass new! !!Expression class methodsFor: 'private-instance creation' stamp: 'jmi 4/24/2000 17:46'!newVariable: aStringOrSymbol	"Answer a new instance of the variable expression"	^ self variableClass new value: aStringOrSymbol asSymbol! !!Expression class methodsFor: 'private-tokenization' stamp: 'jmi 4/23/2000 20:10'!lastUnparenthesized: tokenMatrix in: expression	"Answer the position of the last unparenthesized operator, lowest in the order of operations, in expression"	| level substring safeToRemoveParenthesis wentHigh wentBackLow |	level _ 0.	"safeToRemoveParenthesis _ ((expression at: 1) = $() and: [(expression at: expression size) = $)]."	safeToRemoveParenthesis _ (expression beginsWith: '(') & (expression endsWith: ')').	wentHigh _ wentBackLow  _ false.tokenMatrix reverseDo:[:tokens |	expression size to: 1 by: -1 do:	[:position |		(expression at: position) = $)		ifTrue: [ level _ level + 1.  wentHigh _ true ]		ifFalse:		[			(expression at: position) = $(			ifTrue: [ level _ level - 1 ]			ifFalse:			[				level = 0				ifTrue:				[					wentHigh					ifTrue: [ wentBackLow _ true ].					substring _ expression copyFrom: position to: expression size.					tokens do:					[:token |						(substring beginsWith: token) ifTrue: [ ^ { position. substring copyFrom: 1 to: token size } ].					].				].			].		].		(level > 0) & wentBackLow		ifTrue: [ safeToRemoveParenthesis _ false ].		(level > 0) ifTrue: [ wentHigh _ true ].	].].safeToRemoveParenthesisifTrue:[	^ { 1. '(' }]ifFalse:[	"Not found"	^ { 0. '' }].! !!Expression class methodsFor: 'private-tokenization' stamp: 'jmi 4/23/2000 20:07'!tokenize: aString	"Answer an ordered collection of 1, 2, or 3 elements"	| expression tokens position operator |		"Remove whitespace"	expression _ aString withBlanksCondensed copyReplaceAll: ' ' with: ''.		"Convert any multicharacter exponential operation selectors to a single character"	expression _ expression copyReplaceAll: '**' with: '^'.	expression _ expression copyReplaceAll: 'raisedTo:' with: '^'.				"I need a way to search for all the operations calling the searcher only once.					The simplest solution would be to just assign a single character token for each					multicharacter operator"		"Find the position of the first unparenthesized binary operation"	tokens _ self lastUnparenthesized: self orderOfOperationsMatrix in: expression.		"Unpack the data answered"	position _ tokens at: 1.	operator _ tokens at: 2.	tokens _ nil.		"If position is zero, it means the expression cannot be parsed"	(position = 0)	ifTrue:	[			"Don't generate an error, simply return an empty OrderedCollection"		^ #()		"self error: 'expression cannot be parsed'."	]	ifFalse:	[			"Answer the expression with outer parens removed"		(operator = '(')		ifTrue:		[			^ { expression copyFrom: (operator size + 1) to: (expression size - 1) } as: OrderedCollection		].			"If the operator is not the first or last character, it's a binary operation"		((position > 1) and: [ position < expression size ])		ifTrue:		[				"Split the string into 3 parts (ie: tokenize the binary expression)"			tokens _ {						expression copyFrom: 1 to: (position - 1).						expression copyFrom: position to: (position + operator size - 1).						expression copyFrom: (position + operator size) to: expression size					} as: OrderedCollection.				"Convert the power operation back to something understood by Squeak"			tokens replaceAll: '^' with: 'raisedTo:'.		]		ifFalse:	"Otherwise the operation is unary (need to check for a postfix operation, and determine ordering)"		[				"Split the string into 2 parts (ie: tokenize the unary operation)"			tokens _ {						expression copyFrom: 1 to: operator size.						expression copyFrom: (operator size + 1) to: expression size					} as: OrderedCollection.				"Convert negated operator to a message squeak understands"			tokens replaceAll: '-' with: 'negated'.			tokens replaceAll: '+' with: 'abs'.		].			"Answer the tokenized form"		^ tokens	].! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:17'!constantClass	"Answer the subclass used for constants"	^ ExpressionConstant! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 20:36'!cosineClass	"Answer the class used for cosine"	^ ExpressionCos! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:04'!differenceClass	"Answer the subclass used for subtraction"	^ ExpressionSubtraction! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:07'!exponentialClass	"Answer the subclass used for power"	^ ExpressionExponential! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 18:55'!naturalLogarithmClass	"Answer the class used for natual logarithms"	^ ExpressionLn! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:04'!productClass	"Answer the subclass used for multiplication"	^ ExpressionMultiplication! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:05'!quotientClass	"Answer the subclass used for division"	^ ExpressionDivision! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 20:36'!sineClass	"Answer the class used for sine"	^ ExpressionSin! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:03'!sumClass	"Answer the class used for addition"	^ ExpressionAddition! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 20:35'!tangentClass	"Answer the class used for tangent"	^ ExpressionTan! !!Expression class methodsFor: 'private-subclass' stamp: 'jmi 4/23/2000 17:17'!variableClass	"Answer the subclass used for variables"	^ ExpressionVariable! !!Expression class methodsFor: 'order of operations' stamp: 'jmi 4/26/2000 12:57'!orderOfOperationsMatrix	"Answer a matrix of the order of operations.	The higher in the table an operation is, the higher its precedence.	Operations on the same row have the same precedence"	"if two operations with the same precedence have the same exact characters except one has more at the beginning		(ie: 'sin' and 'arcsin')	then the larger one will NEVER actually be matched.	The Solution:		Give the longer one higher precedence	This may not be the best solution, but it seems to work in any case I can think of"	^ #(			#( 'arcSin' 'arcCos' 'arcTan' )			#( 'ln' 'sin' 'cos' 'tan' )			#( '^' )			#( '*' '/' )			#( '+' '-' )		)! !!Expression class methodsFor: 'instance creation' stamp: 'jmi 4/24/2000 17:45'!newFromString: aString	"Answer an instance of me with the value aString"	| tokens |		"If it's all digits or periods, it's a literal constant"	(aString detect: [:c | c isDigit ifTrue: [ false ] ifFalse: [ c ~= $. ] ] ifNone: [ nil ]) = nil	ifTrue:	[		^ self newConstant: aString.	].		"All letters means it's a variable name"	"aString isAllLetters"	(aString detect: [:c | c isLetter not] ifNone: [nil]) = nil	ifTrue:	[		^ self newVariable: aString.	].		"If aString is neither a number, nor a valid variable name,		aString must have multiple parts, so tokenize it."	tokens _ self tokenize: aString.		"3 indicates a binary operation (firstExpression, operator, secondExpression)"	tokens size = 3	ifTrue:	[		^ (Expression newFromString: (tokens at: 1))				perform:	(tokens at: 2) asSymbol				with:		(Expression newFromString: (tokens at: 3))	].		"2 indicates a unary operation (operator, expression)"	tokens size = 2	ifTrue:	[		^ (Expression newFromString: (tokens at: 2)) perform: (tokens at: 1) asSymbol	].			"1 indicates a parenthesized operation."	tokens size = 1	ifTrue:	[		^ Expression newFromString: (tokens at: 1).	].	"Anything else means I couldn't parse an expression from the string"^ nil.! !!Expression class methodsFor: 'class initialization' stamp: 'jmi 5/16/2000 15:18'!initialize	"Expression initialize"	Zero _ self newConstant: 0.	One _ self newConstant: 1.! !!ExpressionBinary methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:34'!firstTerm	"Answer my first term"	^ firstTerm! !!ExpressionBinary methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:35'!secondTerm	"Answer my second term"	^ secondTerm! !!ExpressionBinary methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:24'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	^ self firstTerm addVariablesTo: (self secondTerm addVariablesTo: aSet)! !!ExpressionBinary methodsFor: 'evaluation' stamp: 'jmi 5/12/2000 23:08'!evaluate	"Answer my evaluated value"	| first second |	(		(first _ self firstTerm evaluate) notNil	and:		[(second _ self secondTerm evaluate) notNil]	)	ifTrue:	[		^ (first perform: self operation with: second)	]	ifFalse:	[		^ nil	]! !!ExpressionBinary methodsFor: 'evaluation' stamp: 'jmi 5/2/2000 19:12'!evaluateAt: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first second |	(		(first _ self firstTerm evaluateAt: aDictionaryOrNumber) notNil	and:		[(second _ self secondTerm evaluateAt: aDictionaryOrNumber) notNil]	)	ifTrue:	[		^ (first perform: self operation with: second)	]	ifFalse:	[		^ nil	]! !!ExpressionBinary methodsFor: 'evaluation' stamp: 'jmi 5/12/2000 16:23'!partialEvaluationAt: anAssociation	"Evaluate my expression using the value association"	| first second |	(		(first _ self firstTerm partialEvaluationAt: anAssociation) notNil	and:		[(second _ self secondTerm partialEvaluationAt: anAssociation) notNil]	)	ifTrue:	[		^ (first perform: self operation with: second)	]	ifFalse:	[		^ nil	]! !!ExpressionBinary methodsFor: 'printing' stamp: 'jmi 4/26/2000 10:58'!printSqueak	"Answer a string representation of myself"	^ '(', self firstTerm printSqueak, ' ', self operation printString, ' ', self secondTerm printSqueak, ')'! !!ExpressionBinary methodsFor: 'printing' stamp: 'jmi 4/23/2000 17:30'!printString	"Answer a string representation of myself"	^ '(', self firstTerm printString, self operationString, self secondTerm printString, ')'! !!ExpressionBinary methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 17:04'!firstTerm: firstExpression secondTerm: secondExpression	"Learn both of my terms"	firstTerm _ firstExpression.		"Allow the second expression to be a literal instead of just an expression"	secondExpression isNumber	ifTrue:	[		secondTerm _ self class newConstant: secondExpression.	]	ifFalse:	[		secondTerm _ secondExpression.	].	^ self simplify! !!ExpressionBinary methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 17:18'!reduceConstantSubexpressions	"collapse any constant subexpressions"	self isConstantExpression	ifTrue:	[		"Reduce to a single constant"		^ self class newConstant: self evaluate	]	ifFalse:	[		^ self	]! !!ExpressionBinary methodsFor: 'testing' stamp: 'jmi 5/15/2000 22:18'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	"This should do a tree comparison rather than printString."	^	(self operation == arg operation)	and:		[			(self firstTerm = arg firstTerm)		and:			[self secondTerm = arg secondTerm]		].! !!ExpressionBinary methodsFor: 'testing' stamp: 'jmi 4/23/2000 17:28'!isConstantExpression	"Answer true if I only contain constants,	 answer false if I contain variables"	^ self firstTerm isConstantExpression and: [ self secondTerm isConstantExpression ]! !!ExpressionAddition methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:31'!operation	"Answer the symbol for the operation I represent"	^ #+! !!ExpressionAddition methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:34'!simplifyExpression	"Answer myself or a simpler version of myself"	self firstTerm = Zero	ifTrue:	[		^ self secondTerm	].	self secondTerm = Zero	ifTrue:	[		^ self firstTerm	].		"Cannot simplify"	^ self! !!ExpressionAddition methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:13'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (self firstTerm privateDerivativeWithRespectTo: aSymbol) + 		(self secondTerm privateDerivativeWithRespectTo: aSymbol)! !!ExpressionExponential methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:37'!base	"Answer my first term"	^ self firstTerm! !!ExpressionExponential methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:38'!exponent	"Answer my second term"	^ self secondTerm! !!ExpressionExponential methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:32'!operation	"Answer the symbol for the operation I represent"	^ #raisedTo:! !!ExpressionExponential methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:32'!operationString	"Answer the string representation for the operation I represent"	^ '^'! !!ExpressionExponential methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:37'!simplifyExpression	"Answer myself or a simpler version of myself"	(		(self base = One)	or:		[	self exponent = Zero	]	)	ifTrue:	"0 raisedTo: 0 should error, but this will return 1 instead (should be fixed later)"	[		^ self class newConstant: 1	].	self base = Zero	ifTrue:	[		^ self class newConstant: 0	].	self exponent = One	ifTrue:	[		^ self base	].		"Cannot simplify"	^ self! !!ExpressionExponential methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:41'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative (this one's gonna take a while... do ln first)"	self exponent isConstantExpression	ifTrue:	[		self base isConstantExpression		ifTrue:			"constant raisedTo: constant"		[		"The derivative of a constant is zero"			^ self class newConstant: 0		]		ifFalse:			"variable raisedTo: constant"		[			^ (self exponent) *				(self base raisedTo: (self exponent - 1)) *				(self base privateDerivativeWithRespectTo: aSymbol)		]	]	ifFalse:	[		self base isConstantExpression		ifTrue:			"constant raisedTo: variable"		[			^ (self base ln) *				(self) *				(self exponent privateDerivativeWithRespectTo: aSymbol)		]		ifFalse:			"variable raisedTo: variable"		[					"^ self class newFromString: '(ln(x)+1)*x^x'"			^ self * ((self exponent * self base ln) privateDerivativeWithRespectTo: aSymbol)		]	].! !!ExpressionMultiplication methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:33'!operation	"Answer the symbol for the operation I represent"	^ #*! !!ExpressionMultiplication methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:39'!simplifyExpression	"Answer myself or a simpler version of myself"	(		(self firstTerm = Zero)	or:		[	self secondTerm = Zero	]	)	ifTrue:	[		^ self class newConstant: 0	].	self firstTerm = One	ifTrue:	[		^ self secondTerm	].	self secondTerm = One	ifTrue:	[		^ self firstTerm	].		"I'm sure this is bad design... multiply shouldn't know how divide works.			I think it should be ok for divide to know how multiply works, since it's			a subclass, but I don't see how that could help in this situation""	theSecond = ('(1/', theFirst, ')')	ifTrue:	[		^ self class newConstant: 1	]."		"Cannot simplify"	^ self! !!ExpressionMultiplication methodsFor: 'symbolic' stamp: 'jmi 5/14/2000 22:25'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ ((self firstTerm privateDerivativeWithRespectTo: aSymbol) * (self secondTerm)) +	  ((self firstTerm) * (self secondTerm privateDerivativeWithRespectTo: aSymbol))! !!ExpressionDivision methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:37'!denominator	"Answer my second term"	^ self secondTerm! !!ExpressionDivision methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:37'!numerator	"Answer my first term"	^ self firstTerm! !!ExpressionDivision methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:32'!operation	"Answer the symbol for the operation I represent"	^ #/! !!ExpressionDivision methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:36'!simplifyExpression	"Answer myself or a simpler version of myself"	self numerator = Zero	ifTrue:	[		^ self class newConstant: 0	].	self denominator = One	ifTrue:	[		^ self numerator	].		"Another example of bad poking around in another object.  It doesn't alter anything, so is this ok?"	(		(self class == self denominator class)	and:		[ self denominator numerator = One ]	)	ifTrue:	[		" x / ( 1 / y ) == x * y "  "I think I could fix this by 'simplifying'		1/x		to	x raisedTo: -1"		^ self numerator * self denominator denominator	].		"Cannot simplify"	^ self! !!ExpressionDivision methodsFor: 'symbolic' stamp: 'jmi 5/14/2000 22:23'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (((self firstTerm privateDerivativeWithRespectTo: aSymbol) * (self secondTerm)) -		((self firstTerm) * (self secondTerm privateDerivativeWithRespectTo: aSymbol))) /								(self secondTerm squared)! !!ExpressionSubtraction methodsFor: 'operation' stamp: 'jmi 4/23/2000 17:33'!operation	"Answer the symbol for the operation I represent"	^ #-! !!ExpressionSubtraction methodsFor: 'private-initialization' stamp: 'jmi 5/15/2000 22:40'!simplifyExpression	"Answer myself or a simpler version of myself"	"If I check on the first term, it will produce an infinite loop,  negated does 0 - term.... begins with zero..."	self secondTerm = Zero	ifTrue:	[		^ self firstTerm	].		"Cannot simplify"	^ self! !!ExpressionSubtraction methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:15'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (self firstTerm privateDerivativeWithRespectTo: aSymbol) -			(self secondTerm privateDerivativeWithRespectTo: aSymbol)! !!ExpressionUnary methodsFor: 'accessors' stamp: 'jmi 4/23/2000 18:26'!term	"Answer my term"	^ term! !!ExpressionUnary methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:26'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	^ self term addVariablesTo: aSet! !!ExpressionUnary methodsFor: 'evaluation' stamp: 'jmi 5/2/2000 19:17'!evaluate	"Answer my evaluated value"	| first |	(first _ self term evaluate) notNil	ifTrue:	[		^ (first perform: self operation)	]	ifFalse:	[		^ nil	]! !!ExpressionUnary methodsFor: 'evaluation' stamp: 'jmi 5/2/2000 19:14'!evaluateAt: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first |	(first _ self term evaluateAt: aDictionaryOrNumber) notNil	ifTrue:	[		^ (first perform: self operation)	]	ifFalse:	[		^ nil	]! !!ExpressionUnary methodsFor: 'evaluation' stamp: 'jmi 5/12/2000 16:25'!partialEvaluationAt: anAssociation	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."	| first |	(first _ self term partialEvaluationAt: anAssociation) notNil	ifTrue:	[		^ (first perform: self operation)	]	ifFalse:	[		^ nil	]! !!ExpressionUnary methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:42'!printSqueak	"Answer a string representation of myself"	"^ '(', self term printSqueak, ') ', self operation printString"	^ self term printSqueak, ' ', self operation printString! !!ExpressionUnary methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:49'!printString	"Answer a string representation of myself"	^ self operationString, '(', self term printString, ')'	"^ self operationString, ' ', self term printString, ''"! !!ExpressionUnary methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 17:19'!reduceConstantSubexpressions	"collapse any constant subexpressions"	self isConstantExpression	ifTrue:	[		"Reduce to a single constant"		^ self class newConstant: self evaluate	]	ifFalse:	[		^ self	]! !!ExpressionUnary methodsFor: 'private-initialization' stamp: 'jmi 4/24/2000 17:07'!term: anExpression	"Learn my term"	term _ anExpression.	^ self simplify! !!ExpressionUnary methodsFor: 'testing' stamp: 'jmi 5/15/2000 22:21'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	"This should do a tree comparison rather than printString."	^	(self operation == arg operation)	and:		[ self term = arg term ].! !!ExpressionUnary methodsFor: 'testing' stamp: 'jmi 4/23/2000 18:27'!isConstantExpression	"Answer true if I only contain constants,	 answer false if I contain variables"	^ self term isConstantExpression! !!ExpressionCos methodsFor: 'operation' stamp: 'jmi 4/23/2000 20:25'!operation	"Answer the symbol for the operation I represent"	^ #cos! !!ExpressionCos methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:13'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (self term privateDerivativeWithRespectTo: aSymbol) * (self term sin negated)! !!ExpressionLn methodsFor: 'operation' stamp: 'jmi 4/23/2000 18:28'!operation	"Answer the symbol for the operation I represent"	^ #ln! !!ExpressionLn methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:14'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (self term privateDerivativeWithRespectTo: aSymbol) / (self term)! !!ExpressionSin methodsFor: 'operation' stamp: 'jmi 4/23/2000 20:22'!operation	"Answer the symbol for the operation I represent"	^ #sin! !!ExpressionSin methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:14'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (self term privateDerivativeWithRespectTo: aSymbol) * (self term cos)! !!ExpressionTan methodsFor: 'operation' stamp: 'jmi 4/23/2000 20:32'!operation	"Answer the symbol for the operation I represent"	^ #tan! !!ExpressionTan methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:15'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative"	^ (self term privateDerivativeWithRespectTo: aSymbol) / (self term cos squared)! !!ExpressionValue methodsFor: 'accessors' stamp: 'jmi 4/23/2000 17:22'!value	"Answer my value"	^ value! !!ExpressionValue methodsFor: 'printing' stamp: 'jmi 4/25/2000 12:38'!printSqueak	"Answer a string representation of myself"	^ self printString! !!ExpressionValue methodsFor: 'printing' stamp: 'jmi 4/26/2000 13:00'!printString	"Answer a string representation of myself"	^ self value asString! !!ExpressionValue methodsFor: 'private-initialization' stamp: 'jmi 5/14/2000 22:30'!value: aValue	"Learn my value"	"aValue isNumber	ifTrue:	["		"Floating point math is 1000 times faster than Fractional"		value _ aValue "	]	ifFalse:	[		value _ aValue	]"! !!ExpressionValue methodsFor: 'operation' stamp: 'jmi 5/15/2000 22:24'!operation	"Values don't HAVE an operation, but need something distinct to tell them apart from the other expressions"	^ nil! !!ExpressionValue methodsFor: 'testing' stamp: 'jmi 5/15/2000 22:25'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	"This should do a tree comparison rather than printString."	^	(self operation == arg operation)	and:		[ self value = arg value ].! !!ExpressionConstant methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:25'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	^ aSet! !!ExpressionConstant methodsFor: 'evaluation' stamp: 'jmi 5/2/2000 17:42'!evaluate	"Evaluate my expression"	^ self value! !!ExpressionConstant methodsFor: 'evaluation' stamp: 'jmi 5/14/2000 22:20'!evaluateAt: aDictionaryOrNumber	"I am a constant.  I don't care what you pass me.  I always answer my value."	^ self value! !!ExpressionConstant methodsFor: 'evaluation' stamp: 'jmi 5/12/2000 16:28'!partialEvaluationAt: anAssociation	"I am a constant.  I don't care what you pass me.  I always answer my value."	^ self class newConstant: self value! !!ExpressionConstant methodsFor: 'printing' stamp: 'jmi 5/14/2000 22:22'!printString	"Answer a string representation of myself"	self value < 0	ifTrue:	[		"This is so I don't have to add a negation operator"			"The parser doesn't know the difference between			binary subtraction and unary minus.  It assumes any			operation right after an open parenthesis is unary"		^ '(', self value asString, ')'	]	ifFalse:	[		^ self value asString	]! !!ExpressionConstant methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:13'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative (always zero)"	^ self class newConstant: 0! !!ExpressionConstant methodsFor: 'testing' stamp: 'jmi 4/25/2000 13:10'!isConstantExpression	"Answer true since I'm a constant"	^ true! !!ExpressionVariable methodsFor: 'as yet unclassified' stamp: 'jmi 4/26/2000 10:35'!addVariablesTo: aSet	"Answer aSet after adding to aSet any variables I might contain"	aSet add: self value.	^ aSet! !!ExpressionVariable methodsFor: 'evaluation' stamp: 'jmi 5/2/2000 19:18'!evaluateAt: aDictionaryOrNumber	"Evaluate my expression using the dictionary of values, indexed by variable name.	If a number is passed in, all variables are evaluated using this value."		"Could this check be slowing things down? I doubt it... it's that dictionary"	aDictionaryOrNumber isNumber	ifTrue:	[		^ aDictionaryOrNumber 	]	ifFalse:	[		^ (aDictionaryOrNumber at: self value ifAbsent: [ nil ]) 	"What is a valid return value for an undefined variable?"	]! !!ExpressionVariable methodsFor: 'evaluation' stamp: 'jmi 5/12/2000 16:27'!partialEvaluationAt: anAssociation	"Evaluate my expression using the value association"	anAssociation key == self value	ifTrue:	[		^ self class newConstant: anAssociation value 	]	ifFalse:	[		^ self class newVariable: self value	]! !!ExpressionVariable methodsFor: 'symbolic' stamp: 'jmi 4/26/2000 11:15'!privateDerivativeWithRespectTo: aSymbol	"Answer my derivative (always one or zero)"	(self value = aSymbol)	ifTrue:	[		^ self class newConstant: 1.	]	ifFalse:	[		^ self class newConstant: 0.	]! !!ExpressionVariable methodsFor: 'testing' stamp: 'jmi 5/15/2000 22:25'!= arg	"Answer whether I am EXACTLY like the other expression (not necessarily the same object)"	"This should do a tree comparison rather than printString."	^	(self operation == arg operation)	and:		[ self value == arg value ].! !!ExpressionVariable methodsFor: 'testing' stamp: 'jmi 4/25/2000 13:10'!isConstantExpression	"Answer true if I'm a constant"	^ false! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/16/2000 09:00'!function	"Answer my function"	^ function! !!FunctionGraph methodsFor: 'accessors/modifiers' stamp: 'jmi 5/16/2000 09:01'!function: aFunction	"Learn my function"	function _ aFunction.		"Determine how much the function needs to be resized to fit on the form"	scaleFactor _ ((extent x min: extent y) / function maxPlanarExtent) asFloat.		"This is so it doesn't have to be converted to a point later			(a scalar is first converted to a point when doing arithmetic between the two)"	scaleFactor _ scaleFactor @ scaleFactor.! !!FunctionGraph methodsFor: 'calculation' stamp: 'jmi 5/16/2000 09:01'!convertTo2d: anArrayOf3Numbers	"Answer screen cordinates for the 3d point		Add depth perception and invert the y-axiz (screen cordinates are backwards from cartesian)"	| depthPerceptionFactor |	depthPerceptionFactor _ pointOfView / (pointOfView - (anArrayOf3Numbers at: 2)).	^ ((anArrayOf3Numbers at: 1) * depthPerceptionFactor) @		((anArrayOf3Numbers at: 3) * depthPerceptionFactor negated).! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 5/16/2000 12:55'!displayForm	"Display the form"	form displayAt: position.		"Allow the screen to refresh if in Morphic"	World ~~ nil	ifTrue:	[	World doOneCycle.	].! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 5/16/2000 10:02'!graph	"Graph it!!"	function evaluateOn: self.		"Hack to display the last form"	self displayForm.! !!FunctionGraph methodsFor: 'drawing' stamp: 'jmi 5/16/2000 22:48'!lineFrom: firstPoint to: secondPoint	"Draw a line between the two points"	| begin end |		"If either point is invalid, return"	firstPoint ifNil: [ ^ self ].	secondPoint ifNil: [ ^ self ].	"Check for change in time"	lastTime ~= (firstPoint at: 4)	ifTrue:	[			"Don't display the blank white form"		lastTime ~~ nil ifTrue: [ self displayForm.].		lastTime _ firstPoint at: 4.		form fillWhite.	"This takes a little longer than just creating a new form,							but doesn't cause as much garbage collection"	].		"Rotate each point"	begin _ pointRotation rotatePointWithYZReversed: firstPoint.	end _ pointRotation rotatePointWithYZReversed: secondPoint.		"Convert each point to screen cordinates"	begin _ self convertTo2d: begin.	end _ self convertTo2d: end.		"Scale and translate the coordinates"	begin _ begin * scaleFactor + translationFactor.	end _ end * scaleFactor + translationFactor.		"Draw the line!!"	lineDrawer drawFrom: begin to: end withFirstPoint: true.! !!FunctionGraph methodsFor: 'initialization' stamp: 'jmi 5/16/2000 12:17'!extent: aPoint	"Learn my extent"	"This has become my 'initialize' method"	extent _ aPoint.	translationFactor _ extent / 2.0.	pointOfView _ 20.0.	lastTime _ nil.	form _ (Form extent: extent) fillWhite.	position _ 0@0.	self updateLineDrawer.! !!FunctionGraph methodsFor: 'initialization' stamp: 'jmi 5/16/2000 12:02'!turn: zAngle tilt: xAngle twist: yAngle		"Build the rotation matrix"	pointRotation _ PointRotation turn: zAngle tilt: xAngle twist: yAngle.! !!FunctionGraph methodsFor: 'initialization' stamp: 'jmi 5/16/2000 09:36'!updateLineDrawer	"Make a new line drawer"	lineDrawer _ BitBlt 		destForm: form		sourceForm: (Form extent: 1@1) fillBlack		fillColor: Color black		combinationRule: Form over		destOrigin: 0@0		"If I set the origin here, do I not have to add it later?!!"		sourceOrigin: 0 @ 0		extent: extent		clipRect: (1@1 extent: extent).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/14/2000 17:24'!example	"Example of what you can do with a graph"	self testFunction: (FunctionNd forExpression3d: '0' asExpression).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 22:56'!example2d	"Example of what you can do with a graph"	| function |	function _ FunctionTransformRotate new					function: (FunctionNd forExpression2d: '(sin(x))' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 22:58'!example2d2	"Example of what you can do with a graph"	| function |	function _ FunctionTransformRotate new					function: (FunctionNd forExpression2d: '(25-x^2)^0.5' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 18:30'!example3d	"Example of what you can do with a graph""	self test3d: '(sin(x)+sin(y))'."	| graph function expression |	expression _ ('(sin(x)+sin(y))' asExpression).	function _ FunctionNd forExpression3d: expression.		"This is the setting I used when testing Lex's code"	function		extent: 10		resolution: 20.	graph _ self forFunction: function.	graph graph! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 12:55'!example3dPolar	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression3d: ('3' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 18:30'!example3dTimeTest	"Example of what you can do with a graph"		"Do the 3d stuff!!""	^ MessageTally time: [ 100 timesRepeat: [graph graph ]]."	^ MessageTally time: [100 timesRepeat: [	self example3d ]]! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:40'!example4d	"Example of what you can do with a graph"		"Hypersphere!!"	self test4d: '(30-x^2-y^2-t^2)^0.5'.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:36'!example4d2	"Example of what you can do with a graph"	self test4d: '(sin(x)+sin(t+y))'.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 23:35'!example4d2transform	"Example of what you can do with a graph"	self testFunction: (FunctionTransformTwist new function: (FunctionNd forExpression4d: '(sin(x)+sin(t+y))')).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:41'!example4d3	"Example of what you can do with a graph"	self test4d: '(sin(t+x)+sin(t*y))'.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 13:39'!example4dPolar	"Example of what you can do with a graph"	| function |		"Hypersphere!!"	function _ FunctionNdPolar forExpression4d: '3' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:42'!example4dPolar2	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression4d: 'x' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:42'!example4dPolar3	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolar forExpression4d: '(100*sin(2*t*x)*sin(2*t*y))^0.5' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:42'!example4dPolar4	"Example of what you can do with a graph"	| function |	function _ FunctionNdPolarCylindrical forExpression4d: '(10*sin(t*x)*sin(t*y))^0.5' asExpression.	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 14:16'!example4dPolar4transform	"Example of what you can do with a graph"	| function |	function _ FunctionTransformPolarCylindrical new					function: (FunctionNd forExpression4d: '(10*sin(t*x)*sin(t*y))^0.5' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/16/2000 15:43'!example4dPolarTransform	"Example of what you can do with a graph"	| function |		"Hypersphere!!"	function _ FunctionTransformPolar new				function: (FunctionNd forExpression4d: '3' asExpression).	self testFunction: function.! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:31'!test2d: anExpression	self testFunction: (FunctionNd forExpression2d: anExpression).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:31'!test3d: anExpression	self testFunction: (FunctionNd forExpression3d: anExpression).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/15/2000 17:34'!test4d: anExpression	self testFunction: (FunctionNd forExpression4d: anExpression).! !!FunctionGraph class methodsFor: 'example' stamp: 'jmi 5/14/2000 19:11'!testFunction: aFunction	"Example of what you can do with a graph"	| graph |	graph _ self forFunction: aFunction.	graph graph! !!FunctionGraph class methodsFor: 'instance creation' stamp: 'jmi 5/16/2000 09:48'!forFunction: aFunction	^ (super new extent: 640@480 "640@480")		turn:	(Float pi / 4) negated		tilt:		(Float pi / 4)		twist:	0;		function: aFunction.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/16/2000 13:08'!evaluate: partialExpression at: currentDimension with: thePoint on: aGraph		"Skip the dependent variable dimension"	currentDimension = 2	ifTrue:	[	^ self evaluateX: partialExpression with: thePoint on: aGraph. ].		"BAD BAD HORRIBLE CODE!!  Must make a better way."		"lastXRow needs to be initialized before the y loop"	currentDimension = 3	ifTrue:	[	lastXRow atAllPut: nil	].		"Loop across the currentDimension's axiz"	(nInterval at: currentDimension)	do:	[:value |			"getPointAt: needs all the values to make a copy (or convert to polar, etc...)"		thePoint at: currentDimension put: value.			"Partially evaluate the expression so it's smaller (evaluates faster) as the recursion continues"		self			evaluate: (partialExpression partialEvaluationAt: ((nVariable at: currentDimension) -> value))			at:		currentDimension - 1			with:	thePoint			on:		aGraph.	].! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/15/2000 17:18'!evaluateOn: aGraph	"Loop through each independent axis and tell aGraph what lines to draw"	| nValues |		"Provide at least 4 slots for values, since point rotation etc... needs that many"	nValues _ Array new: (4 max: self dimensions).	nValues atAllPut: 0.	^ self		evaluate: expression		at: self dimensions		with: nValues		on: aGraph.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/16/2000 13:00'!evaluateX: partialExpression with: thePoint on: aGraph	"Loop through the innermost axis (the x-axis)"	| lastPoint currentPoint position |		"Initializations"	position _ 1.	lastPoint _ nil.		"The innermost loop!!"	(nInterval at: 1) do:	[:value |			"update the 'x' value"		thePoint at: 1 put: value.					"evaluateAt: is faster than partialEvaluationAt: so just use that for the innermost loop"		currentPoint _ self							getPointAt: (partialExpression evaluateAt: value)							with: thePoint."Is it faster to nil check here and never even call lineFrom:to:?"			"Graph the 2 lines from the currentPoint"		aGraph lineFrom: lastPoint to: currentPoint.		aGraph lineFrom: (lastXRow at: position) to: currentPoint.			"increment counters/update temporary variables"		lastXRow at: position put: currentPoint.		position _ position + 1.		lastPoint _ currentPoint.	].! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/16/2000 15:12'!getPointAt: aNumber with: thePoint	aNumber == nil	ifTrue: [ ^ nil ].		"add the dependent variable value"	thePoint at: 2 put: aNumber.	^ self transform: thePoint.! !!FunctionNd methodsFor: 'calculation' stamp: 'jmi 5/16/2000 15:12'!transform: thePoint	"default action is to return a copy"	"If you don't return a copy, a bunch of points get graphed instead of a wireframe (try it and see)"^ thePoint copy.! !!FunctionNd methodsFor: 'info for graph' stamp: 'jmi 5/16/2000 17:02'!maxPlanarExtent	"Answer the maximum (diagonal, or whatever) extent possible in the xy plane"	| nExtent |		"Calculate the extents for each dimension"	nExtent _ nMax - nMin.	self dimensions < 3	ifTrue:	[		^ (nExtent at: 1) abs	]	ifFalse:	[			"Diagonal made between the width and depth"		^ ((nExtent at: 1) squared + (nExtent at: 3) squared) sqrt.	].! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/14/2000 22:56'!dimensions	"Answer my number of dimensions"	^ dimensions! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/15/2000 17:39'!expression: anExpression	"Learn my expression"	expression _ anExpression asExpression.	self changed.! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/16/2000 15:15'!extent: aNumber resolution: aPositiveInteger	"Learn my extent and resolution"	self extent: aNumber.	self resolution: aPositiveInteger.		"update the nStep variable (or nInterval if I try that again)"	self updateInterval.		"create the temporary holder for the innermost loop"	lastXRow _ Array new: resolution + 1.	lastXRow atAllPut: nil.! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/16/2000 13:51'!initialize: independentVariables	"nDimensional initialization (currently only known to support 3d/4d)		it may work fine for other dimensions, but I haven't tested those yet"		"A function of 1 variable accounts for 2 dimensions.					of 2 variables accounts for 3 dimensions, etc..."	dimensions _ independentVariables size + 1.		"Set default extent/resolution"	self		extent: 4.0 * Float pi		resolution: 30.		"Create the array of variable names"	nVariable _ Array new: self dimensions.	nVariable at: 1 put: (independentVariables at: 1).	nVariable at: 2 put: #dependentVariable.		"Never actually used.  Just a placeholder."	2 to: independentVariables size do:	[:index |		nVariable at: index + 1 put: (independentVariables at: index).	].! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/14/2000 23:29'!resolution	"Answer my resolution"	^ resolution! !!FunctionNd methodsFor: 'initialization' stamp: 'jmi 5/16/2000 13:49'!updateInterval	"Set the loop intervals"	| nStep |	nStep _ ((nMax - nMin) / resolution) asArray.	nInterval _ Array new: self dimensions.	1 to: self dimensions do:	[:dimension |		nInterval at: dimension put: (					(nMin at: dimension) to:					(nMax at: dimension) + 0.01 by:					(nStep at: dimension)					).	].	! !!FunctionNd methodsFor: 'private-initialization' stamp: 'jmi 5/14/2000 23:30'!extent: aNumber	"Set the extent for the n-dimensional cube"	nMax _ Array new: self dimensions.	nMax atAllPut: (aNumber / 2.0) asFloat.	nMin _ nMax negated.! !!FunctionNd methodsFor: 'private-initialization' stamp: 'jmi 5/14/2000 23:30'!resolution: aPositiveInteger	"Learn my resolution"	resolution _ aPositiveInteger.! !!FunctionNd methodsFor: 'for prototype interface-accessors/modifiers' stamp: 'jmi 5/14/2000 18:54'!expressionString	"Answer my expression string"	^ expression printString! !!FunctionNd methodsFor: 'for prototype interface-accessors/modifiers' stamp: 'jmi 5/14/2000 19:42'!expressionString: aStringOrText	"Learn my expression"	| tmpExpression ok |	ok _ true.	[		tmpExpression _ aStringOrText asString asExpression.	]	ifError: [:err :msg | ok _ false ].	tmpExpression ifNil: [ ok _ false ].	ok ifTrue:	[		self expression: tmpExpression.	].	^ ok.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/17/2000 09:08'!forExpression2d: anExpression	"Answer a Function for anExpression"	^ self forExpression: anExpression ofVariables: { #x }.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/15/2000 16:04'!forExpression3d: anExpression	"Answer a Function for anExpression"	^ self forExpression: anExpression ofVariables: { #x. #y }.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/15/2000 16:14'!forExpression4d: anExpression	"Answer a Function for anExpression"	^ self forExpression: anExpression ofVariables: { #x. #y. #t }.! !!FunctionNd class methodsFor: 'instance creation' stamp: 'jmi 5/15/2000 15:57'!forExpression: anExpression ofVariables: anArray	"Answer a Function for anExpression"	"The second dimension is always the dependent variable, and thus shouldn't be listed in anArray.	For example, say you want a 2d Function (y in terms of x).  You would pass { #x }.	If you wanted a 3d function, say z in terms of x and y, you simply pass { #x. #y }.	If you want a 4d function, say z in terms of x y and t, you simply pass { #x. #y. #t }.	Order DOES matter, meaning the first variable always corresponds to the x-axis,		second to y-axis, and third to the time axis"	^ super new		initialize: anArray;		expression: anExpression.! !!FunctionNdPolar methodsFor: 'calculation' stamp: 'jmi 5/15/2000 17:16'!transform: thePoint	"convert nValue to polar (spherical) form"	| theta phi r t |	theta _ thePoint at: 1.	r _ thePoint at: 2.	phi _ thePoint at: 3.	t _ thePoint at: 4.		^ {			r * t cos * phi sin * theta cos.			r * t cos * phi cos.				"My coordinate system transposes y and z for some reason..."			r * t cos * phi sin * theta sin.	"...probably because I think of y as up, and z as normal to the screen..."											"and the rest of the world thinks of z as up, and y as normal to the screen"			t			"z * t sin" "Corrupts the cartesian time coordinate..."		}! !!FunctionNdPolar methodsFor: 'initialization' stamp: 'jmi 5/14/2000 16:01'!extent: aNumber	| tmpArray |	"Ignore the passed value.  Set the polar values instead."	nMax _ Array new: self dimensions.	nMax atAllPut: Float halfPi.	nMin _ nMax negated.	tmpArray _ {		2.0 * Float pi.		0. "Dependent variable placeholder"		Float pi	}.	1 to:  (3 min: self dimensions) do:	[:dimension |		nMin at: dimension put: 0.0.		nMax at: dimension put: (tmpArray at: dimension).	].! !!FunctionNdPolarCylindrical methodsFor: 'calculation' stamp: 'jmi 5/15/2000 17:17'!transform: thePoint	"convert nValue to polar (cylindrical) form"	| theta phi r t |	theta _ thePoint at: 1.	r _ thePoint at: 2.	phi _ thePoint at: 3.	t _ thePoint at: 4.		^ {			r * "t sin *" phi sin * theta cos.			r * "t sin *" phi cos.				"My coorinate system transposes y and z for some reason..."			r * "t sin *" phi sin * theta sin.			t			"z * t sin" "Corrupts the cartesian time coordinate..."		}! !!FunctionNdPolarCylindrical methodsFor: 'initialization' stamp: 'jmi 5/14/2000 23:33'!extent: aNumber	| tmpArray |	"Ignore the passed value.  Set the polar values instead."	nMax _ Array new: self dimensions.	nMax atAllPut: Float pi.	nMin _ Array new: self dimensions.	nMin atAllPut: 0.	tmpArray _ {		2.0 * Float pi.		0. "Dependent variable placeholder"		Float pi	}.	1 to:  (3 min: self dimensions) do:	[:dimension |		nMax at: dimension put: (tmpArray at: dimension).	].! !!FunctionTransform methodsFor: 'function' stamp: 'jmi 5/16/2000 14:08'!evaluateOn: aGraph	"Loop through each independent axis and tell aGraph what lines to draw"	graph _ aGraph.	^ function evaluateOn: self! !!FunctionTransform methodsFor: 'function' stamp: 'jmi 5/16/2000 13:59'!maxPlanarExtent	^ function maxPlanarExtent.! !!FunctionTransform methodsFor: 'graph' stamp: 'jmi 5/16/2000 16:39'!function: aFunction	function _ aFunction.! !!FunctionTransform methodsFor: 'graph' stamp: 'jmi 5/16/2000 16:39'!lineFrom: firstPoint to: secondPoint	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	^ graph		lineFrom:	(self transform: firstPoint)		to:			(self transform: secondPoint).! !!FunctionTransform methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 23:52'!initialize	"default is to just make a PointRotation.  Subclasses override, and don't have to worry about redefining new"	pointRotation _ PointRotation new.! !!FunctionTransform methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 14:13'!transform: thePoint	"Default action is to do nothing"	^ thePoint! !!FunctionTransform class methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 23:48'!new	"auto-initialize"	^ super new initialize! !!FunctionTransformRotate methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 22:55'!lineFrom: firstPoint to: secondPoint	| lastRotationValue |	((firstPoint == nil) or: [ secondPoint == nil ] ) ifTrue: [ ^ self ].	lastRotationValue _ 0.	graph lineFrom: firstPoint to: secondPoint.	Float halfPi / 4 to: Float pi * 2.0 + 0.01 by: Float halfPi / 4 do:	[:i |		graph			lineFrom:	(self transform: secondPoint by: lastRotationValue)			to:			(self transform: secondPoint by: i).		graph			lineFrom:	(self transform: firstPoint by: i)			to:			(self transform: secondPoint by: i).		lastRotationValue _ i.	].! !!FunctionTransformRotate methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 23:51'!transform: thePoint by: angle	pointRotation turn: 0.0 tilt: angle twist: 0.0.	^ pointRotation rotatePoint: thePoint.! !!FunctionTransformTwist methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 23:50'!transform: thePoint	pointRotation turn: 0.0 tilt: 0.0 twist: (thePoint at: 4) / 4.0.	^ pointRotation rotatePoint: thePoint.! !!Number methodsFor: 'mathematical functions' stamp: 'jmi 5/2/2000 19:22'!negativeRaisedToNonIntegerPower: aNumber	"I'm getting really annoyed with the pink boxes!!"	"this assumes the message is sent to a negative number!!"	"		IMAGINARY: negative raisedTo: (odd/even)		NEGATIVE:	negative raisedTo: (odd/odd)		POSITIVE:	negative raisedTo: (even/odd)	"	| returnValue exponent |	exponent _ aNumber asFraction.	exponent denominator even	ifTrue:	[		"self error: self printString, ' raised to non integer power, and result is complex'."		^ nil "0.0" "Just testing something."	]	ifFalse:	[		returnValue _ self negated raisedTo: aNumber.		exponent numerator even		ifTrue:		[			^ returnValue		]		ifFalse:		[			^ returnValue negated		].	].! !!Number methodsFor: 'mathematical functions' stamp: 'jmi 5/2/2000 18:19'!raisedTo: aNumber 	"Answer the receiver raised to aNumber."	aNumber isInteger ifTrue:		["Do the special case of integer power"		^ self raisedToInteger: aNumber].	self < 0 ifTrue:		[ "self error: self printString, ' raised to a non-integer power'"			^ self negativeRaisedToNonIntegerPower: aNumber		 ].	aNumber = 0 ifTrue: [^ 1].		"Special case of exponent=0"	(self = 0) | (aNumber = 1) ifTrue:		[^ self].						"Special case of exponent=1"	^ (aNumber * self ln) exp		"Otherwise use logarithms"! !!Float methodsFor: 'mathematical functions' stamp: 'jmi 5/2/2000 17:57'!raisedTo: aNumber	"Answer the receiver raised to aNumber."	aNumber isInteger ifTrue:		["Do the special case of integer power"		^ self raisedToInteger: aNumber].	self < 0.0 ifTrue:		[ "self error: self printString, ' raised to a non-integer power'"			^ self negativeRaisedToNonIntegerPower: aNumber ].	0.0 = aNumber ifTrue: [^ 1.0].				"special case for exponent = 0.0"	(self= 0.0) | (aNumber = 1.0) ifTrue: [^ self].	"special case for self = 1.0"	^ (self ln * aNumber asFloat) exp			"otherwise use logarithms"! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 11:21'!reset	"Reset to the identity matrix"	a _ 1.	b _ 0.	c _ 0.	d _ 0.	e _ 1.	f _ 0.	g _ 0.	h _ 0.	i _ 1.! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 22:48'!rotatePoint: array	"Answer the product of rotation matrix by point array"	"It's probably backwards, so be sure to check it."		"Answer the rotated point"	^ {		(a * (array at: 1)) + (d * (array at: 2)) + (g * (array at: 3)).		(b * (array at: 1)) + (e * (array at: 2)) + (h * (array at: 3)).		(c * (array at: 1)) + (f * (array at: 2)) + (i * (array at: 3)).		array at: 4	}.! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 22:47'!rotatePointWithYZReversed: array	"Answer the product of rotation matrix by point array"	"It's probably backwards, so be sure to check it."		"Answer the rotated point"	^ {		(a * (array at: 1)) + (d * (array at: 3)) + (g * (array at: 2)).		(b * (array at: 1)) + (e * (array at: 3)) + (h * (array at: 2)).		(c * (array at: 1)) + (f * (array at: 3)) + (i * (array at: 2)).		array at: 4	}.! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 11:40'!setZRotation: angle	"Set the matrix used to rotate angle radians around the z-axiz"	a _ angle cos.	b _ angle sin negated.	c _ 0.	d _ angle sin.	e _ angle cos.	f _ 0.	g _ 0.	h _ 0.	i _ 1.! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 23:33'!turn: zAngle tilt: xAngle twist: yAngle	"Build the rotation matrix"		"Start with the identity matrix"	self reset.		"Then multiply it by the rotation matricies"	"self zRotationOptimized: zAngle."	self setZRotation: zAngle.	self xRotationOptimized: xAngle.	self yRotationOptimized: yAngle.! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 11:29'!xRotation: angle	| a11 a12 a13 a21 a22 a23 a31 a32 a33 b11 b12 b13 b21 b22 b23 b31 b32 b33 |	"Answer the matrix used to rotate angle radians around the x-axiz"	a11 _ a.	a12 _ b.	a13 _ c.	a21 _ d.	a22 _ e.	a23 _ f.	a31 _ g.	a32 _ h.	a33 _ i."	{		1. 0. 0.		0. angle cos. angle sin negated.		0. angle sin. angle cos	}"	b11 _ 1.	b12 _ 0.	b13 _ 0.	b21 _ 0.	b22 _ angle cos.	b23 _ angle sin negated.	b31 _ 0.	b32 _ angle sin.	b33 _ angle cos.	a _ (a11 * b11) + (a12 * b21) + (a13 * b31).	b _ (a11 * b12) + (a12 * b22) + (a13 * b32).	c _ 	(a11 * b13) + (a12 * b23) + (a13 * b33).	d _ 	(a21 * b11) + (a22 * b21) + (a23 * b31).	e _ 	(a21 * b12) + (a22 * b22) + (a23 * b32).	f _ 	(a21 * b13) + (a22 * b23) + (a23 * b33).	g _ (a31 * b11) + (a32 * b21) + (a33 * b31).	h _ (a31 * b12) + (a32 * b22) + (a33 * b32).	i _ (a31 * b13) + (a32 * b23) + (a33 * b33).! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 12:12'!xRotationOptimized: angle	| a12 a13 a22 a23 a32 a33 b22 b23 b32 b33 |	"Answer the matrix used to rotate angle radians around the x-axiz"	a12 _ b.	a13 _ c.	a22 _ e.	a23 _ f.	a32 _ h.	a33 _ i."	{		1. 0. 0.		0. angle cos. angle sin negated.		0. angle sin. angle cos	}""	b11 _ 1.""	b12 _ 0.""	b13 _ 0.""	b21 _ 0."	b22 _ angle cos.	b23 _ angle sin negated."	b31 _ 0."	b32 _ angle sin.	b33 _ angle cos.	b _ (a12 * b22) + (a13 * b32).	c _ 	(a12 * b23) + (a13 * b33).	e _ 	(a22 * b22) + (a23 * b32).	f _ 	(a22 * b23) + (a23 * b33).	h _ (a32 * b22) + (a33 * b32).	i _ (a32 * b23) + (a33 * b33).! !!PointRotation methodsFor: 'as yet unclassified' stamp: 'jmi 5/16/2000 11:33'!yRotation: angle	| a11 a12 a13 a21 a22 a23 a31 a32 a33 b11 b12 b13 b21 b22 b23 b31 b32 b33 |	"Answer the matrix used to rotate angle radians around the y-axiz"	a11 _ a.	a12 _ b.	a13 _ c.	a21 _ d.	a22 _ e.	a23 _ f.	a31 _ g.	a32 _ h.	a33 _ i."	{		angle cos. 0. angle sin.		0. 1. 0.		angle sin negated. 0. angle cos	}."	b11 _ angle cos.	b12 _ 0.	b13 _ angle sin.	b21 _ 0.	b22 _ 1.	b23 _ 0.	b31 _ angle sin negated.	b32 _ 0.	b33 _ angle cos.	a _ (a11 * b11) + (a12 * b21) + (a13 * b31).	b _ (a11 * b12) + (a12 * b22) + (a13 * b32).	c _ 	(a11 * b13) + (a12 * b23) + (a13 * b33).	d _ 	(a21 * b11) + (a22 * b21) + (a23 * b31).	e _ 	(a21 * b12) + (a22 * b22) + (a23 * b32).	f _ 	(a21 * b13) + (a22 * b23) + (a23 * b33).	g _ (a31 * b11) + (a32 * 